 void buildSources(){sources.clear();String def=null,q1080=null,q720=null,q480=null,q320=null;HashMap<String,String> ep=currentEpisode();if(ep!=null){def=ep.get("url");q1080=ep.get("url_1080");q720=ep.get("url_720");q480=ep.get("url_480");q320=ep.get("url_320");}else{def=getIntent().getStringExtra("url");q1080=getIntent().getStringExtra("url_1080");q720=getIntent().getStringExtra("url_720");q480=getIntent().getStringExtra("url_480");q320=getIntent().getStringExtra("url_320");}boolean cellular=isCellular();if(cellular){addSource(q720);addSource(q480);addSource(q320);addSource(q1080);}else{addSource(q1080);addSource(q720);addSource(q480);addSource(q320);}addSource(def);}
