 void savePlaybackProgress(boolean completed){if(live)return;int pos=safePosition();long dl=durationMs();int dur=dl>Integer.MAX_VALUE?Integer.MAX_VALUE:(int)Math.max(0,dl);android.content.SharedPreferences sp=getSharedPreferences("gp",0);if(!seriesId.isEmpty()&&!episodeId.isEmpty()){if(completed||(dur>0&&pos>=dur-3000)){sp.edit().remove(resumeKey()).apply();return;}if(pos<3000||dur<=0)return;try{org.json.JSONObject r=new org.json.JSONObject();r.put("episode_id",episodeId);r.put("episode_title",episodeTitle);r.put("season_number",seasonNumber);r.put("episode_number",episodeNumber);r.put("position",pos);r.put("duration",dur);r.put("updated_at",System.currentTimeMillis());sp.edit().putString(resumeKey(),r.toString()).apply();}catch(Exception ignored){}return;}if(movieId.isEmpty())return;if(completed||(dur>0&&pos>=dur-3000)){sp.edit().remove(movieResumeKey()).apply();return;}if(pos<3000||dur<=0)return;try{org.json.JSONObject r=new org.json.JSONObject();r.put("movie_id",movieId);r.put("movie_title",movieTitle);r.put("movie_poster",moviePoster);r.put("movie_landscape",movieLandscape);r.put("position",pos);r.put("duration",dur);r.put("updated_at",System.currentTimeMillis());sp.edit().putString(movieResumeKey(),r.toString()).apply();}catch(Exception ignored){}}
